# BeforeRunIt for bash. Generated by `beforerunit init bash`; add to ~/.bashrc:
#   eval "$(beforerunit init bash)"
# Draws a risk line under the prompt while you type. Toggle with @TOGGLE_NAME@.

[[ $- == *i* ]] || return 0
[[ -n ${__bri_loaded-} ]] && return 0
[[ ${TERM-} == dumb ]] && return 0
__bri_loaded=1

__bri_bin=@BIN@
__bri_lib=@LIB@
__bri_sid=bash-$$-${EPOCHSECONDS:-$RANDOM}
__bri_mode=
__bri_display=@DISPLAY@
__bri_pw=0
__bri_pwok=
__bri_drawn=
__bri_last=
__bri_fast=

if [[ -n ${NO_COLOR-} ]]; then
  __bri_caps=n
else
  case ${COLORTERM-} in
    *truecolor* | *24bit*) __bri_caps=ti ;;
    *) case ${TERM-} in
         *256color* | *kitty* | *alacritty* | *ghostty* | *wezterm*) __bri_caps=2i ;;
         *) __bri_caps=1 ;;
       esac ;;
  esac
fi

{ exec {__bri_fd}>/dev/tty; } 2>/dev/null || __bri_fd=2

if [[ -z ${BEFORERUNIT_NO_BUILTIN-} && -n $__bri_lib && -r $__bri_lib ]] &&
   enable -f "$__bri_lib" beforerunit_query 2>/dev/null; then
  __bri_fast=1
  beforerunit_query init "$__bri_bin"
fi

# Visible width of the last prompt line. Only needed once the input may wrap,
# so prompts with expensive command substitutions are not expanded twice.
__bri_prompt_width() {
  local p=${PS1@P}
  p=${p##*$'\n'}
  while [[ $p == *$'\001'*$'\002'* ]]; do p=${p%%$'\001'*}${p#*$'\002'}; done
  local re=$'\e\\[[0-9;?]*[a-zA-Z]'
  while [[ $p =~ $re ]]; do p=${p/"${BASH_REMATCH[0]}"/}; done
  __bri_pw=${#p}
  __bri_pwok=1
}

__bri_paint() {
  [[ -z $__bri_pwok ]] && (( ${#READLINE_LINE} > ${COLUMNS:-80} / 2 )) && __bri_prompt_width
  if [[ -n $__bri_fast ]]; then
    beforerunit_query draw "$READLINE_LINE" "$READLINE_POINT" "${COLUMNS:-80}" "$__bri_pw" \
      "$__bri_sid" "$__bri_mode" "$PWD" "$EUID" "" "$$" "$__bri_caps"
    [[ -n $BRI_OUT ]] && printf '%s' "$BRI_OUT" >&"$__bri_fd"
  else
    local out
    out=$("$__bri_bin" query --shell bash --from-start ${__bri_drawn:+--drawn} --cols "${COLUMNS:-80}" \
      --point "$READLINE_POINT" --pw "$__bri_pw" --sid "$__bri_sid" --mode "$__bri_mode" \
      --cwd "$PWD" --euid "$EUID" --pid "$$" --caps "$__bri_caps" -- "$READLINE_LINE" 2>/dev/null)
    [[ $out == "$__bri_last" ]] && return 0
    __bri_last=$out
    case $out in
      *$'\eD'*) __bri_drawn=1 ;;
      ?*) __bri_drawn= ;;
    esac
    [[ -n $out ]] && printf '%s' "$out" >&"$__bri_fd"
  fi
  return 0
}

__bri_clear() {
  if [[ -n $__bri_fast ]]; then
    beforerunit_query clear "$READLINE_LINE" "$READLINE_POINT" "${COLUMNS:-80}" "$__bri_pw" "$__bri_sid"
    [[ -n $BRI_OUT ]] && printf '%s' "$BRI_OUT" >&"$__bri_fd"
  elif [[ -n $__bri_drawn ]]; then
    "$__bri_bin" query --shell bash --from-start --drawn --clear --cols "${COLUMNS:-80}" \
      --pw "$__bri_pw" --sid "$__bri_sid" -- "$READLINE_LINE" >&"$__bri_fd" 2>/dev/null
  fi
  __bri_drawn=
  __bri_last=
  return 0
}

__bri_repaint() {
  [[ -n $__bri_fast ]] && beforerunit_query forget
  __bri_drawn=
  __bri_last=
  __bri_paint
}

# Bracketed paste: read the pasted text up to ESC [201~ and insert it at once.
__bri_paste() {
  local buf= chunk rest
  while IFS= read -r -t 2 -d $'\e' chunk; do
    buf+=$chunk
    IFS= read -r -t 1 -n 5 rest
    [[ $rest == '[201~' ]] && break
    buf+=$'\e'$rest
  done
  buf=${buf//$'\r\n'/$'\n'}
  buf=${buf//$'\r'/$'\n'}
  READLINE_LINE=${READLINE_LINE:0:READLINE_POINT}$buf${READLINE_LINE:READLINE_POINT}
  ((READLINE_POINT += ${#buf}))
  __bri_paint
}

__bri_toggle() {
  case ${__bri_mode:-$__bri_display} in
    always) __bri_mode=risky-only ;;
    risky-only) __bri_mode=off ;;
    *) __bri_mode=always ;;
  esac
  __bri_paint
}

__bri_precmd() {
  local s=$?
  if [[ -n $__bri_fast ]]; then
    beforerunit_query forget
    # A ghost line left behind by Ctrl-C sits where the new prompt starts.
    [[ -n $BRI_OUT ]] && printf '%s' "$BRI_OUT" >&"$__bri_fd"
  elif [[ -n $__bri_drawn ]]; then
    printf '\e[J' >&"$__bri_fd"
  fi
  __bri_drawn=
  __bri_last=
  __bri_pwok=
  return $s
}

__bri_ble_update() {
  [[ -n $__bri_ble_dirty ]] || return 0
  __bri_ble_dirty=
  local line=$_ble_edit_str out
  if [[ -n $__bri_fast ]]; then
    beforerunit_query line "$line" "${_ble_edit_ind:-0}" "${COLUMNS:-80}" 0 "$__bri_sid" \
      "$__bri_mode" "$PWD" "$EUID" "" "$$" "$__bri_caps"
    out=$BRI_OUT
  else
    out=$("$__bri_bin" query --shell bash --line-only --cols "${COLUMNS:-80}" --sid "$__bri_sid" \
      --mode "$__bri_mode" --cwd "$PWD" --euid "$EUID" --pid "$$" --caps "$__bri_caps" -- "$line" 2>/dev/null)
  fi
  [[ $out == "$__bri_last" ]] && return 0
  __bri_last=$out
  if [[ -n $out ]]; then
    ble/edit/info/show ansi "$out"
  else
    ble/edit/info/default
  fi
}

__bri_ble_observe() {
  __bri_ble_dirty=1
  _ble_textarea_render_defer=1
}

__bri_ble_preexec() {
  [[ -n $__bri_fast ]] && beforerunit_query clear "" 0 "${COLUMNS:-80}" 0 "$__bri_sid" >/dev/null
  __bri_last=
}

__bri_setup_ble() {
  ble/array#push _ble_edit_dirty_observer __bri_ble_observe
  blehook textarea_render_defer+=__bri_ble_update
  blehook PREEXEC+=__bri_ble_preexec
  blehook PRECMD+='__bri_last='
  ble-bind -x @TOGGLE_BLE@ __bri_toggle 2>/dev/null
}

# Every key keeps its normal function and then refreshes the ghost line, via
# private \C-x\C-b sequences. The macro bindings live in an inputrc written by
# `beforerunit init`, loaded in one go so shell startup stays fast.
__bri_setup_readline() {
  local km=emacs
  [[ -o vi ]] && km=vi-insert
  if ! bind -m "$km" -f @INPUTRC@ 2>/dev/null; then
    local l
    while IFS= read -r l; do
      [[ $l == '#'* ]] || bind -m "$km" "$l"
    done < <("$__bri_bin" init bash --inputrc)
  fi
  bind -m "$km" -x '"\C-x\C-b=": __bri_paint'
  bind -m "$km" -x '"\C-x\C-b-": __bri_clear'
  bind -m "$km" -x '"\C-x\C-b+": __bri_repaint'
  bind -m "$km" -x '"\e[200~": __bri_paste'
  bind -m "$km" -x "\"@TOGGLE@\": __bri_toggle"
}

if [[ -n ${BLE_VERSION-} ]]; then
  __bri_setup_ble
else
  __bri_setup_readline
  if [[ ${PROMPT_COMMAND@a} == *a* ]]; then
    PROMPT_COMMAND=(__bri_precmd "${PROMPT_COMMAND[@]}")
  else
    PROMPT_COMMAND="__bri_precmd${PROMPT_COMMAND:+;$PROMPT_COMMAND}"
  fi
fi
